# Path: ./api/v1/marketing/gemini_architect.py import os import json import google.generativeai as genai import argparse  def generate_dominion_content(asset_name):     # 1. Load the Registry     with open('api/v1/marketing/assets_registry.json', 'r') as f:         registry = json.load(f)      # 2. Get specific instructions or fallback to general tactical      asset_data = registry.get(asset_name, registry.get("tactical_fallback"))     directive = asset_data.get("prompt_injection", "Focus on elite performance.")     context = asset_data.get("context", "Tactical fitness.")      # 3. Setup Gemini 1.5/3.0     genai.configure(api_key=os.getenv("GEMINI_API_KEY"))     model = genai.GenerativeModel('gemini-1.5-pro')      # 4. Construct the High-Resolution Prompt     master_prompt = f"""     SYSTEM ROLE: You are the ResoFlex AI Architect. Your tone is Stoic, Elite, and Technical.          ASSET CONTEXT: {context}     PRIME DIRECTIVE: {directive}          TASK: Create a 2-part broadcast for the Global Operator.     1. HOOK: A high-tension opening line about dominion or calibration.     2. CALL TO ACTION: Direct them to the paystack.shop/resonancefitness-store to secure their mandate.          CONSTRAINT: No emojis except 🧬. Use sparse, powerful language. Max 25 words.     """      response = model.generate_content(master_prompt)     return response.text.strip()  if __name__ == "__main__":     parser = argparse.ArgumentParser()     parser.add_argument("--asset", required=True)     args = parser.parse_args()          content = generate_dominion_content(args.asset)     print(content) 
