cat > api/v1/marketing/assets_registry.json <<EOF # Path: ./scripts/ingest_capcut.py import os import shutil import sys  def ingest(source_path, target_number):     """     Usage: python3 scripts/ingest_capcut.py /path/to/capcut_export.mp4 5     This will replace video 5.mp4 with the new export.     """     target_dir = "public/assets"     target_filename = f"{target_number}.mp4"     final_path = os.path.join(target_dir, target_filename)      # 1. Move and rename     shutil.copy(source_path, final_path)          # 2. Run Size Guard     os.system(f"python3 scripts/size_guard.py {final_path}")          print(f"✅ INGEST_SUCCESS: {target_filename} is ready for 4x4 rotation.")  if __name__ == "__main__":     if len(sys.argv) > 2:         ingest(sys.argv[1], sys.argv[2]) EOF
cat > api/v1/marketing/assets_registry.json <<EOF # Path: ./scripts/sync_registry.py import os import json  REGISTRY_PATH = 'api/v1/marketing/assets_registry.json' ASSETS_DIR = 'public/assets'  def sync_registry():     # 1. Load existing registry     if os.path.exists(REGISTRY_PATH):         with open(REGISTRY_PATH, 'r') as f:             registry = json.load(f)     else:         registry = {}      print("🔄 SYNCING_REGISTRY: Checking for new neural assets...")      # 2. Scan for numerical mp4 files     new_assets_found = 0     for file in os.listdir(ASSETS_DIR):         if file.endswith(".mp4") and file.split('.')[0].isdigit():             if file not in registry:                 # 3. Inject Smart Metadata for the new asset                 registry[file] = {                     "context": f"Tactical Evolution Footage: Session {file.split('.')[0]}",                     "prompt_injection": "Focus on high-intensity physical calibration and the stoic mindset of the ResoFlex operator. Use elite, technical vocabulary.",                     "alt_text": f"ResoFlex Operator Training Module {file.split('.')[0]}"                 }                 print(f"➕ ADDED_TO_BRAIN: {file}")                 new_assets_found += 1      # 4. Save updated registry     if new_assets_found > 0:         with open(REGISTRY_PATH, 'w') as f:             json.dump(registry, f, indent=2)         print(f"✅ SYNC_COMPLETE: {new_assets_found} new assets registered.")     else:         print("💤 NO_CHANGES: Registry is already up to date.")  if __name__ == "__main__":     sync_registry() EOF
